import type { BufferGeometry, Camera, Mesh, Object3D, ShaderMaterial, Texture, Vector2 } from 'three'

/**
 * Слой графа сцены для объёмов, которые рисует DepthVolumePass. Основной
 * RenderPass рисует слой 0 камеры и эти объёмы не видит; пасс включает слой на
 * камере только на время своего рендера. Рендер объёма вне пасса (запекание
 * импостора туманности) включает слой на своей камере сам.
 */
export const DEPTH_VOLUME_LAYER = 30

/**
 * Слой меша сильной зоны чёрной дыры: рисует BlackHolePass после объёмов,
 * сэмплируя копию кадра. Основной проход слой не видит; кликовый рейкастер
 * включает его у себя (Engine)
 */
export const BLACK_HOLE_LAYER = 29

/**
 * Слой оверлеев (линии орбит): рисует OverlayPass поверх уже лензированного
 * кадра, чтобы схематичные линии не искривлялись линзами чёрной дыры.
 * Основной проход слой не видит
 */
export const OVERLAY_LAYER = 28

/**
 * Слой прозрачного перед линзой: LensFrontSorter переносит сюда на один кадр
 * прозрачные объекты тел, стоящих перед активной чёрной дырой; LensFrontPass
 * рисует их поверх лензированного кадра и возвращает на слой 0. Основной
 * проход слой не видит
 */
export const LENS_FRONT_LAYER = 27

/**
 * Второй слой перенесённых объектов, пишущих глубину (препасс кольца,
 * билборды камней): LensFrontPass дописывает их глубину в буфер с глубиной
 * сцены — её читают атмосфера и копия для объёмов
 */
export const LENS_FRONT_DEPTH_LAYER = 26

/**
 * Потребитель копии кадра (BlackHolePass): перед рендером получает цвет и
 * глубину сцены, после — отвязывается, чтобы рендер вне пасса шёл без них
 */
export interface SceneFrameConsumer extends Object3D {
  /** skyLayer — слой видимого неба кадра (SkyLayer), того же размера, что копии */
  bindSceneFrame(sceneColor: Texture, sceneDepth: Texture, skyLayer: Texture, logFarFactor: number): void
  unbindSceneFrame(): void
}

export function isSceneFrameConsumer(object: Object3D): object is SceneFrameConsumer {
  const candidate = object as Partial<SceneFrameConsumer>
  return typeof candidate.bindSceneFrame === 'function' && typeof candidate.unbindSceneFrame === 'function'
}

/**
 * Объём, чей марш режется по глубине сцены (см. DepthVolumePass).
 *
 * Живёт в графе сцены (матрицы считает основной проход), но рисуется пассом
 * после сцены. Перед рендером пасс привязывает копию глубины сцены, после —
 * отвязывает: любой другой рендер объёма (запекание) идёт без обрезки.
 */
export interface DepthVolume extends Object3D {
  /** Opt in to a shared render/resolve for consecutive direct transparent draws.
   * Bind/unbind and object callbacks may only refresh this draw's uniforms;
   * they must not mutate other volumes, renderer state or invoke nested renders.
   * Material callbacks, children, shared materials and scaled/temporal draws
   * keep their separate render boundaries. Original object callback roots remain. */
  readonly supportsDepthVolumeBatch?: boolean
  /**
   * Радиус описанной сферы прокси в ЛОКАЛЬНЫХ единицах объёма (масштаб мира
   * пасс применяет сам). Порядок рисования — по дальней кромке
   * (расстояние до центра + радиус): объём, охватывающий камеру и остальные,
   * ложится первым, а не по совпадающему центру. Не задан — по центру.
   */
  readonly boundingRadius?: number
  /**
   * @param sceneDepth копия depth-текстуры сцены, лог-глубина three в .r
   * @param resolution размер таргета в пикселях: gl_FragCoord → uv копии
   * @param logFarFactor log2(far + 1) камеры — знаменатель лог-глубины three
   */
  bindSceneDepth(sceneDepth: Texture, resolution: Vector2, logFarFactor: number): void
  unbindSceneDepth(): void
}

/** Optional capability: reconstruct a reduced image, raymarching depth edges natively. */
export interface ScaledDepthVolume extends DepthVolume {
  readonly resolutionScale: number
  bindLowResolution(texture: Texture, size: Vector2): void
  unbindLowResolution(): void
}

export function isScaledDepthVolume(volume: DepthVolume): volume is ScaledDepthVolume {
  const candidate = volume as Partial<ScaledDepthVolume>
  return typeof candidate.resolutionScale === 'number' &&
    typeof candidate.bindLowResolution === 'function' && typeof candidate.unbindLowResolution === 'function'
}

/** Opt-in shader modes DEPTH_VOLUME_RECONSTRUCT / DEPTH_VOLUME_FALLBACK.
 * A closed BackSide proxy covers each pixel once; depth comes from the scene sampler.
 * Callbacks must only refresh the current draw's uniforms (as for a multipass material). */
export type StencilDepthVolume = ScaledDepthVolume & Mesh<BufferGeometry, ShaderMaterial> & {
  readonly supportsStencilReconstruction: true
  /** MSAA composition is safe only when every viewport sample has proxy coverage. */
  coversReconstructionViewport?(camera: Camera): boolean
}

export function isStencilDepthVolume(volume: DepthVolume): volume is StencilDepthVolume {
  const candidate = volume as Partial<StencilDepthVolume>
  return isScaledDepthVolume(volume) && candidate.supportsStencilReconstruction === true &&
    candidate.isMesh === true && candidate.material?.isShaderMaterial === true
}

/** Optional local-position metadata for independent, per-volume history. */
export interface TemporalDepthVolume extends ScaledDepthVolume {
  readonly temporalBlend: number
  readonly temporalRevision: number
  bindTemporalCapture(jitter: number): void
  unbindTemporalCapture(): void
}

export function isTemporalDepthVolume(volume: DepthVolume): volume is TemporalDepthVolume {
  const candidate = volume as Partial<TemporalDepthVolume>
  return isScaledDepthVolume(volume) && typeof candidate.temporalBlend === 'number' &&
    typeof candidate.temporalRevision === 'number' && typeof candidate.bindTemporalCapture === 'function' &&
    typeof candidate.unbindTemporalCapture === 'function'
}

import { BasicDepthPacking, type Object3D, type PerspectiveCamera, type Texture, type WebGLRenderer, type WebGLRenderTarget, Vector2, Vector3 } from 'three'
import { DepthCopyPass, Pass } from 'postprocessing'
import type { DepthVolumeRegistry } from '@/core/services/DepthVolumeRegistry'
import { DEPTH_VOLUME_LAYER, type DepthVolume } from '@/core/graphic/passes/DepthVolume'
import { DepthVolumeResolutionRenderer } from './DepthVolumeResolutionRenderer'
import { depthVolumeBatchEnd, renderDepthVolumeBatch } from './DepthVolumeBatchRenderer'

/** Тип упаковки глубины библиотека объявляет, но не экспортирует — берём из сигнатуры Pass */
type DepthPacking = Parameters<Pass['setDepthTexture']>[1]

/** Фильтр передних объёмов (LensFrontSorter подходит структурно) */
export interface FrontVolumeFilter {
  isFrontVolume(volume: DepthVolume): boolean
}

/**
 * Объёмы от дальнего к ближнему по дальней кромке: расстояние центра до камеры
 * + радиус описанной сферы (boundingRadius в мировом масштабе). Объёмы с общим
 * центром (кокон туманности и пояс вокруг одной звезды) так упорядочиваются по
 * охвату, а не по порядку регистрации — блендинг «поверх» зависит от порядка.
 */
export function orderFarToNear(volumes: readonly DepthVolume[], camera: Object3D): DepthVolume[] {
  const cameraWorld = camera.getWorldPosition(new Vector3())
  const position = new Vector3()
  const scale = new Vector3()
  const farExtent = new Map<DepthVolume, number>()
  for (const volume of volumes) {
    volume.getWorldPosition(position)
    volume.getWorldScale(scale)
    const worldRadius = (volume.boundingRadius ?? 0) * Math.max(Math.abs(scale.x), Math.abs(scale.y), Math.abs(scale.z))
    farExtent.set(volume, position.distanceTo(cameraWorld) + worldRadius)
  }
  return [...volumes].sort((a, b) => farExtent.get(b)! - farExtent.get(a)!)
}

/**
 * Объёмы в target камерой на DEPTH_VOLUME_LAYER: каждому на время рендера
 * привязана копия глубины сцены. Маска камеры и автообновление теней
 * возвращаются
 */
export function drawDepthVolumes(
  renderer: WebGLRenderer,
  target: WebGLRenderTarget | null,
  camera: PerspectiveCamera,
  volumes: readonly DepthVolume[],
  sceneDepth: Texture,
  resolution: Vector2,
  scaled?: DepthVolumeResolutionRenderer
): void {
  const mask = camera.layers.mask
  const shadowMapAutoUpdate = renderer.shadowMap.autoUpdate
  const logFarFactor = Math.log2(camera.far + 1)

  try {
    camera.layers.set(DEPTH_VOLUME_LAYER)
    renderer.shadowMap.autoUpdate = false
    renderer.setRenderTarget(target)
    scaled?.prepare(volumes, resolution)

    const canBatch = target !== null && target.samples > 0 && renderer.autoClear === false && !renderer.xr?.isPresenting
    for (let index = 0; index < volumes.length;) {
      const end = canBatch ? depthVolumeBatchEnd(volumes, index) : index
      if (end - index > 1) {
        renderDepthVolumeBatch(renderer, camera, volumes, index, end, sceneDepth, resolution, logFarFactor)
        index = end
        continue
      }
      const volume = volumes[index++]
      try {
        volume.bindSceneDepth(sceneDepth, resolution, logFarFactor)
        if (scaled) scaled.render(renderer, target, camera, volume, sceneDepth, resolution, logFarFactor)
        else renderer.render(volume, camera)
      } finally {
        volume.unbindSceneDepth()
      }
    }
  } finally {
    camera.layers.mask = mask
    renderer.shadowMap.autoUpdate = shadowMapAutoUpdate
  }
}

/**
 * DepthVolumePass — объёмные эффекты (пыль колец, туманности) поверх
 * отрендеренной сцены с обрывом марша по её глубине.
 *
 * Зачем отдельный пасс. Объём — реймарч на прокси, один фрагмент несёт
 * интеграл вдоль ВСЕГО луча. Аппаратный тест глубины бинарен: он либо срезал
 * объём целиком перед поверхностями (глубина от дальней стенки прокси), либо
 * пропускал целиком вместе с частью ЗА ними (глубина от точки входа) — планета
 * и камни просвечивали сквозь пыль, туманность давала жёсткие вырезы. Честное
 * перекрытие — обрыв марша на глубине сцены, а читать глубину можно только
 * после того, как сцена дорисована.
 *
 * Почему копия глубины. Сцена лежит в inputBuffer, к нему же привязана
 * depth-текстура композера. Рисовать в inputBuffer и сэмплировать его
 * аттачмент — feedback loop, WebGL такой draw отвергает. Поэтому глубина
 * сначала копируется во float-таргет (DepthCopyPass), и объёмы читают копию.
 *
 * Объёмы рисуются В inputBuffer (needsSwap = false) поверх готового кадра, без
 * своей глубины (depthTest/depthWrite OFF у материалов), от дальнего к
 * ближнему по расстоянию до камеры: ближний ложится поверх дальнего (пыль
 * кольца поверх туманности за ним). Атмосфера идёт следом и тонирует их так же,
 * как тонировала бы в основном проходе.
 *
 * Объёмы живут в графе сцены (матрицы считает основной проход) на слое
 * DEPTH_VOLUME_LAYER, который камера обычно не видит; пасс включает слой только
 * на время своего рендера и рендерит каждый объём как корень — обход графа
 * целой сцены второй раз за кадр не нужен. Перед рендером объёму привязывается
 * копия глубины, после — отвязывается: рендер объёма вне пасса (запекание
 * импостора) идёт без обрезки.
 *
 * Объёмы перед активной чёрной дырой пропускаются — их рисует LensFrontPass
 * поверх лензированного кадра.
 */
export class DepthVolumePass extends Pass {
  /** Копия глубины сцены во float-таргет; открыта под тесты */
  public readonly depthCopy: DepthCopyPass

  private readonly sceneCamera: PerspectiveCamera
  private readonly registry: DepthVolumeRegistry
  private readonly front: FrontVolumeFilter | null
  private readonly resolution = new Vector2(1, 1)
  private readonly scaled = new DepthVolumeResolutionRenderer()

  public constructor(camera: PerspectiveCamera, registry: DepthVolumeRegistry, front?: FrontVolumeFilter) {
    super('DepthVolumePass')
    this.sceneCamera = camera
    this.registry = registry
    this.front = front ?? null
    this.needsSwap = false
    this.needsDepthTexture = true
    // BasicDepthPacking → FloatType-таргет, глубина в .r без упаковки
    this.depthCopy = new DepthCopyPass({ depthPacking: BasicDepthPacking })
  }

  public override setDepthTexture(depthTexture: Texture, depthPacking?: DepthPacking): void {
    this.depthCopy.setDepthTexture(depthTexture, depthPacking)
  }

  public override initialize(renderer: WebGLRenderer, alpha: boolean, frameBufferType: number): void {
    this.depthCopy.initialize(renderer, alpha, frameBufferType)
  }

  public override setSize(width: number, height: number): void {
    this.depthCopy.setSize(width, height)
    this.resolution.set(width, height)
  }

  public override render(
    renderer: WebGLRenderer,
    inputBuffer: WebGLRenderTarget | null,
    outputBuffer: WebGLRenderTarget | null,
    deltaTime?: number,
    stencilTest?: boolean
  ): void {
    // Передние объёмы (перед активной линзой) рисует LensFrontPass после линз
    const volumes = orderFarToNear(
      this.registry.volumes().filter((v) => isVisibleInTree(v) && !(this.front?.isFrontVolume(v) ?? false)),
      this.sceneCamera
    )
    if (volumes.length === 0) { this.scaled.prepare(volumes, this.resolution); return }

    this.depthCopy.render(renderer, inputBuffer, outputBuffer, deltaTime, stencilTest)
    drawDepthVolumes(
      renderer,
      this.renderToScreen ? null : inputBuffer,
      this.sceneCamera,
      volumes,
      this.depthCopy.texture,
      this.resolution,
      this.scaled
    )
  }

  public override dispose(): void {
    this.scaled.dispose()
    this.depthCopy.dispose()
    super.dispose()
  }
}

export function isVisibleInTree(object: Object3D): boolean {
  for (let node: Object3D | null = object; node !== null; node = node.parent) {
    if (!node.visible) return false
  }
  return true
}

