import { SceneManager } from '@/core/services/SceneManager'
import { SceneObserver } from '@/core/services/SceneObserver'
import { CameraCollision } from '@/core/services/CameraCollision'
import { Postprocessing } from '@/core/graphic/Postprocessing'
import { config } from '@/core/framework/config'
import { toThreeJSUnits } from '@/core/helpers/scaling'
import { SimulationClock } from '@/core/time/SimulationClock'
import { CameraController } from '@/core/camera/CameraController'
import { UpdateContext } from '@/core/UpdateContext'
import { Clock, PerspectiveCamera, Raycaster, Scene, Vector2, WebGLRenderer } from 'three'
import { BLACK_HOLE_LAYER } from '@/core/graphic/passes/DepthVolume'
import { CSS2DRenderer } from 'three/examples/jsm/renderers/CSS2DRenderer'
import { AstroControls } from '@/core/libs/AstroControls'
import Stats from 'three/examples/jsm/libs/stats.module'
import { clampPixelRatio } from '@/core/graphic/renderingFactories'
import { resolveCrosshairAnchor } from '@/core/helpers/resolveCrosshairAnchor'
import type { AsteroidImpostorLibrary } from '@/core/renderables/DetailedRingStreamingSystem/impostors/AsteroidImpostorLibrary'
import type { NebulaBakeQueue } from '@/core/renderables/Nebula/volume/NebulaBakeQueue'

class Engine {
  private readonly canvas: HTMLCanvasElement
  private readonly overlay: HTMLElement

  private initialized: boolean = false
  private running: boolean = false

  private readonly boundOnResize: () => void
  private readonly boundOnFrameRendered: () => void
  private readonly boundOnClick: (event: MouseEvent) => void
  private readonly boundOnWheel: (event: WheelEvent) => void

  private readonly raycaster: Raycaster = Engine.createRaycaster()

  private static createRaycaster(): Raycaster {
    const raycaster = new Raycaster()
    // Меш чёрной дыры живёт на своём слое (рисует BlackHolePass), а кликается по-прежнему
    raycaster.layers.enable(BLACK_HOLE_LAYER)
    return raycaster
  }
  /**
   * Панель статистики создаётся только когда её показывают: её конструктор
   * строит канвас и берёт 2D-контекст, чего в среде без канваса нет.
   */
  private readonly stats: Stats | null = config('showStats') ? new Stats() : null

  /** Уже выведенные ошибки кадра: постоянный сбой пишет в консоль один раз, а не каждый кадр */
  private readonly reportedFrameErrors: Set<string> = new Set()

  public constructor(
    private sceneManager: SceneManager,
    private sceneObserver: SceneObserver,
    private clock: SimulationClock,
    private camera: CameraController,
    private renderer: WebGLRenderer,
    private labelRenderer: CSS2DRenderer,
    private scene: Scene,
    private renderCamera: PerspectiveCamera,
    private astroControls: AstroControls,
    private renderClock: Clock,
    private postprocessing: Postprocessing,
    private cameraCollision: CameraCollision,
    private readonly asteroidImpostors?: Pick<AsteroidImpostorLibrary, 'pumpFrame'>,
    private readonly nebulaBakes?: Pick<NebulaBakeQueue, 'pumpFrame'>
  ) {
    this.canvas = this.renderer.domElement
    this.overlay = this.labelRenderer.domElement

    if (this.stats) {
      this.stats.showPanel(0)
      this.stats.showPanel(1)
      this.stats.showPanel(2)
    }

    this.boundOnResize = this.onResize.bind(this)
    this.boundOnFrameRendered = this.onFrameRendered.bind(this)
    this.boundOnClick = this.onClick.bind(this)
    this.boundOnWheel = this.onWheel.bind(this)

    addEventListener('resize', this.boundOnResize)
    this.canvas.addEventListener('click', this.boundOnClick)
  }

  public initialize(): void {
    if (this.initialized) return
    this.initialized = true
    this.canvas.id = 'canvas'
    this.canvas.style.position = 'absolute'
    this.canvas.style.zIndex = '99'

    this.overlay.id = 'overlay'

    document.body.appendChild(this.canvas)
    document.body.appendChild(this.overlay)

    if (this.stats) {
      this.stats.dom.style.zIndex = '9999999999999'
      document.body.appendChild(this.stats.dom)
    }

    this.sceneManager.initialize()
    this.postprocessing.initialize()

    this.sceneObserver.observable = this.astroControls
    this.sceneObserver.scene = this.scene

    this.onStart()
  }

  public start(): void {
    if (!this.running) {
      const elapsed = this.renderClock.elapsedTime
      this.renderClock.start()
      this.renderClock.elapsedTime = elapsed
      this.running = true
      if (!this.initialized) this.initialize()

      this.update()
    }
  }

  public stop(): void {
    this.renderer.setAnimationLoop(null)

    if (this.running) {
      const elapsed = this.renderClock.elapsedTime
      this.renderClock.stop()
      // Clock.stop() samples a partial frame. Keep elapsed aligned with deltas
      // already delivered to the simulation.
      this.renderClock.elapsedTime = elapsed
    }

    this.running = false
  }

  public update(): void {
    if (this.running) {
      this.onFrameRendered()
    }
  }

  /**
   * Разборка сценария. Гарда на `running` здесь нет намеренно: метод должен
   * работать и на остановленном движке, иначе выход в меню с последующим
   * входом оставляет предыдущую сцену в графе.
   *
   * Порядок важен: луп останавливается последним — сначала перестаём быть
   * в сцене, потом перестаём её рисовать.
   *
   * Снимается только слушатель `wheel`: он регистрируется в `onStart()` и
   * принадлежит сценарию. Слушатели `resize` и `click` регистрируются в
   * конструкторе и живут всё время жизни движка-контейнера — их снятие здесь
   * означало бы, что после разборки сценария навсегда пропадают обработка
   * ресайза окна и клик-по-объекту-в-прицел.
   */
  public dispose(): void {
    // Цель принадлежит сценарию: освобождаем ссылку до разборки его графа.
    this.camera.stopFollowing()
    this.sceneManager.dispose()
    this.postprocessing.dispose()
    this.sceneObserver.dispose()

    this.canvas.removeEventListener('wheel', this.boundOnWheel)

    this.initialized = false

    this.stop()
  }

  private onStart(): void {
    this.canvas.addEventListener('wheel', this.boundOnWheel)
  }

  private onWheel(event: WheelEvent): void {
    this.camera.adjust(event.deltaY)
  }

  /**
   * Цикл three без защиты: исключение из колбэка обрывает цепочку
   * requestAnimationFrame, а флаг isAnimating остаётся поднят — повторный
   * setAnimationLoop цикл уже не запускает, рендер стоит до выхода в меню.
   * Сбой кадра теряет только этот кадр.
   */
  private onFrameRendered(): void {
    try {
      this.renderFrame()
    } catch (error) {
      this.reportFrameError(error)
    }

    this.renderer.setAnimationLoop(this.boundOnFrameRendered)
  }

  private reportFrameError(error: unknown): void {
    const key = error instanceof Error ? `${error.name}: ${error.message}` : String(error)

    if (this.reportedFrameErrors.has(key)) return

    this.reportedFrameErrors.add(key)
    console.error('[Engine] сбой кадра, кадр пропущен:', error)
  }

  private renderFrame(): void {
    const delta: number = this.renderClock.getDelta()

    this.stats?.update()
    this.clock.advance(delta)
    this.astroControls.movementSpeed = toThreeJSUnits(this.camera.speed)
    this.astroControls.update(delta)

    const ctx: UpdateContext = {
      delta,
      epoch: this.clock.epoch,
      // getElapsedTime() снова вызывает getDelta() и отнимает время работы
      // выше у следующего кадра. Нужен снимок, уже обновлённый в начале кадра.
      elapsed: this.renderClock.elapsedTime,
      camera: this.renderCamera
    }

    this.sceneManager.update(ctx)
    // После обновления позиций тел: тик видит свежие дистанции. Событие от
    // контролов ловит только движение камеры, а тела движутся сами.
    this.sceneObserver.tick(delta)

    const followUpdate = this.camera.updateFollow(this.renderCamera.position)

    if (followUpdate) {
      // SceneObserver по-прежнему выбирает ближайшее тело для свободного полёта,
      // но в follow-режиме вращаться нужно именно вокруг явно выбранной цели.
      this.astroControls.setTarget(followUpdate.targetPosition)
      // Орбитальная дельта — смена сопутствующей системы отсчёта, а не ручной
      // прямолинейный полёт камеры. Коллизии всё ещё проверят ручной остаток.
      this.cameraCollision.translateReferenceFrame(followUpdate.displacement)
    }

    this.cameraCollision.resolve()
    // после коллизии: высота над рельефом — по уже вытолкнутой позиции
    this.astroControls.setSurface(this.cameraCollision.nearestSurface())
    // Импосторы и свечение должны видеть камеру после follow и коллизий.
    this.sceneManager.updateView(this.renderCamera)
    this.labelRenderer.render(this.scene, this.renderCamera)
    this.sceneManager.updateMarkers()
    this.asteroidImpostors?.pumpFrame()
    this.nebulaBakes?.pumpFrame()
    this.postprocessing.render(delta)
  }

  private onResize(): void {
    const { innerHeight, innerWidth } = window

    // Порядок несущий: pixelRatio ДО setSize композера — composer.setSize
    // меряет таргеты в drawing-buffer-пикселях (size × ratio).
    // Кламп 2 — тот же, что в createRenderer (см. renderingFactories).
    this.renderer.setPixelRatio(clampPixelRatio(window.devicePixelRatio, 2))
    this.renderer.setSize(innerWidth, innerHeight)
    this.labelRenderer.setSize(innerWidth, innerHeight)
    this.postprocessing.setSize(innerWidth, innerHeight)
    this.renderCamera.aspect = innerWidth / innerHeight
    this.renderCamera.updateProjectionMatrix()
  }

  private onClick(event: MouseEvent): void {
    const mouse = new Vector2()

    event.preventDefault()

    mouse.x = (event.clientX / window.innerWidth) * 2 - 1
    mouse.y = -(event.clientY / window.innerHeight) * 2 + 1

    this.raycaster.setFromCamera(mouse, this.renderCamera)

    // Список от getObjectsByUserDataProperty уже плоский — рекурсивный
    // пересечь задвоил бы каждый патч кубосферы (сам патч + повторно через
    // траверс его группы, тоже входящей в список)
    const intersects = this.raycaster.intersectObjects(
      this.scene.getObjectsByUserDataProperty('clickable', true),
      false
    )

    if (intersects.length) {
      const target = intersects.find((el) => el.object.userData.clickable !== undefined)

      if (target) resolveCrosshairAnchor(target.object).parent?.add(this.sceneManager.crosshair)
    } else {
      this.sceneManager.crosshair.parent?.remove(this.sceneManager.crosshair)
    }
  }
}

export { Engine }

