// External diagnosis; imports only the frozen production runtime.
window.__connectMemorySoak = async runtimeUrl => {
  const runtime = await import(runtimeUrl)
  const get = name => {
    const c = runtime.getInitializedSimulationRuntime()?.container
    if (!c) throw Error('Runtime not initialized')
    const tokens = [...c.bindings.keys()].filter(t => typeof t === 'object' && t.name === name)
    if (tokens.length !== 1) throw Error('Ambiguous service ' + name)
    return c.get(tokens[0])
  }
  let firstRenderer, exercising = false
  const stats = values => {
    const a = [...values].sort((a,b) => a-b)
    if (!a.length) throw Error('Empty frame window')
    const q = p => a[Math.ceil(a.length*p)-1]
    return {count:a.length,p50:q(.5),p95:q(.95),p99:q(.99),max:a.at(-1),mean:values.reduce((a,b)=>a+b,0)/a.length}
  }
  function snapshot() {
    const renderer=get('Renderer'), scene=get('Scene'), queue=get('NebulaBakeQueue')
    if(firstRenderer && renderer!==firstRenderer) throw Error('Renderer replaced across scenes')
    firstRenderer=renderer
    const streamers=[]
    let sceneObjects=0, meshes=0, instancedMeshes=0
    scene.traverse(object=>{
      sceneObjects++
      if(object.isMesh) meshes++
      if(object.isInstancedMesh) instancedMeshes++
      if(object.pool?.commitUpdates && object.cascades?.managers) streamers.push({name:object.name,info:object.getDebugInfo()})
    })
    return {at:performance.now(),memory:{...renderer.info.memory},programs:renderer.info.programs.length,
      sceneObjects,meshes,instancedMeshes,streamers,pendingBakes:queue.pendingCount,bakeBytes:queue.allocatedBytes,
      volumes:get('DepthVolumeRegistry').volumes().length,canvases:document.querySelectorAll('canvas').length,
      createdWebGLContexts:window.__memorySoakContexts.count(),frame:renderer.info.render.frame,
      camera:get('Camera').position.toArray(),orientation:get('Camera').quaternion.toArray()}
  }
  return window.__memorySoak = {
    snapshot,
    async exercise({durationMs,periodMs=60000,spanTu=2}) {
      if(exercising || !Number.isFinite(durationMs) || durationMs<1000) throw Error('Invalid exercise')
      const engine=get('Engine'), camera=get('Camera'), renderer=get('Renderer')
      const origin=camera.position.clone(), orientation=camera.quaternion.clone()
      const direction=origin.clone().set(1,0,0).applyQuaternion(orientation)
      const descriptor=Object.getOwnPropertyDescriptor(engine,'renderFrame'), original=engine.renderFrame
      if(typeof original!=='function') throw Error('Frame method missing')
      const initial=snapshot(), starts=[],cpu=[],samples=[],poses=[]
      let active=true, start, end, lastSample=-Infinity, timeout
      exercising=true
      try {
        await new Promise((resolve,reject)=>{
          timeout=setTimeout(()=>reject(Error('Memory exercise timed out')),durationMs+60000)
          engine.renderFrame=function(...args) {
            if(!active) return original.apply(this,args)
            const now=performance.now()
            if(start===undefined) start=now
            const elapsed=now-start, phase=Math.min(elapsed,durationMs)/periodMs*Math.PI*2
            camera.position.copy(origin).addScaledVector(direction,Math.sin(phase)*spanTu)
            camera.quaternion.copy(orientation);camera.rotateY(phase);camera.updateMatrixWorld(true)
            starts.push(now)
            try {
              original.apply(this,args)
              end=performance.now();cpu.push(end-now)
              if(elapsed-lastSample>=5000 || elapsed>=durationMs) {
                samples.push({frame:starts.length-1,elapsed,snapshot:snapshot()})
                poses.push({frame:starts.length-1,elapsed,position:camera.position.toArray(),quaternion:camera.quaternion.toArray()})
                lastSample=elapsed
              }
              if(elapsed>=durationMs) {active=false;resolve()}
            } catch(error) {active=false;reject(error)}
          }
        })
        const intervals=starts.slice(1).map((value,i)=>value-starts[i])
        if(starts.length<2 || cpu.length!==starts.length || end-start<durationMs) throw Error('Incomplete exercise')
        return {durationMs,periodMs,spanTu,initial,final:snapshot(),starts,cpu,intervals,samples,poses,
          frameCount:starts.length,elapsedMs:end-start,summary:{intervals:stats(intervals),cpu:stats(cpu)},restoration:true}
      } finally {
        active=false;clearTimeout(timeout)
        if(descriptor) Object.defineProperty(engine,'renderFrame',descriptor);else delete engine.renderFrame
        const after=Object.getOwnPropertyDescriptor(engine,'renderFrame')
        if(!!after!==!!descriptor || (descriptor && ['value','get','set','writable','configurable','enumerable'].some(k=>after[k]!==descriptor[k]))) throw Error('Frame descriptor restoration failed')
        camera.position.copy(origin);camera.quaternion.copy(orientation);camera.updateMatrixWorld(true)
        exercising=false
        if(!camera.position.equals(origin)||!camera.quaternion.equals(orientation)) throw Error('Camera restoration failed')
      }
    },
    restore() {
      if(exercising) throw Error('Exercise still active')
      return window.__memorySoakContexts.restore()
    }
  }
}

