import {preview} from 'vite'
import {chromium} from '@playwright/test'
import {readFileSync,writeFileSync} from 'node:fs'
import {createHash} from 'node:crypto'
import {execFileSync} from 'node:child_process'
import assert from 'node:assert/strict'
const root='benchmark-results/heavy-scenes/',name='production-memory-soak-2026-10-28'
const base='83976aef4e5110bad3f5f5b3914c67a6ea5a841f',codeBase='c00a4de416befd402c3587ccb31e7f2a24e05a1d'
const smoke=process.argv.includes('--smoke'),output=root+name+(smoke?'-smoke':'')+'.json'
const options={smoke,rounds:smoke?0:6,warmupMs:smoke?5000:15000,dwellMs:60000,periodMs:60000,spanTu:2,menuIdleMs:1000,settleFrames:64}
const sha=b=>createHash('sha256').update(b).digest('hex')
const git=(...args)=>execFileSync('git',args,{encoding:'utf8'}).trim()
assert.equal(git('rev-parse','HEAD'),base)
const noChanges=()=>{
  assert.equal(git('diff',codeBase,'--name-only','--','src','tests','package.json','package-lock.json','vite.config.ts'),'')
  assert.equal(git('status','--porcelain','--','src','tests','package.json','package-lock.json','vite.config.ts'),'')
}
noChanges()
const previous=JSON.parse(readFileSync(root+'volume-batch-v2-2026-10-27.json','utf8'))
assert.equal(previous.outcome,'completed')
const sources=[root+name+'.browser.js',root+'run-'+name+'.mjs',root+'gpu-draws-2026-10-27.browser.js',
  ...Object.keys(previous.sourceHashes).filter(p=>p.startsWith('src/')||p.startsWith('tests/')),
  'src/core/Engine.ts','src/ui/mobx/EngineStore.ts','tests/browser/scenarios.soak.ts','tests/browser/scenarioSoak.browser.ts']
const report={base,codeBase,startedAt:new Date().toISOString(),options,frozenBundle:previous.frozenBundle,buildFiles:previous.buildFiles,
  connection:previous.connection,buildInputHashes:previous.sourceHashes,sourceHashes:Object.fromEntries([...new Set(sources)].map(p=>[p,sha(readFileSync(p))])),
  rows:[],errors:[],warnings:[],assetFailures:[],abortedRequests:[],sourceModuleRequests:[],requests:[],cloudResponses:0,outcome:'failed',
  scope:'Same production page/runtime/native renderer across all visits. Forced GC and CDP memory reads outside timed windows. JS isolate heap, embedder heap, ArrayBuffer/external-string backing storage and renderer object counts are distinct from GPU VRAM. No product/quality changes; bounded routes and duration only.'}
const verifyInputs=()=>{
  for(const f of report.buildFiles) assert.equal(sha(readFileSync(report.frozenBundle+'/'+f.path)),f.sha256)
  for(const [path,hash] of Object.entries(report.sourceHashes)) assert.equal(sha(readFileSync(path)),hash,path)
  for(const [path,hash] of Object.entries(previous.sourceHashes).filter(([p])=>p.startsWith('src/')||p.startsWith('tests/'))) assert.equal(sha(readFileSync(path)),hash,path)
  noChanges()
}
verifyInputs();writeFileSync(output,JSON.stringify(report,null,2),{flag:'wx'})
const save=()=>writeFileSync(output,JSON.stringify(report,null,2))
let server,browser,cdp
try {
  server=await preview({build:{outDir:report.frozenBundle},base:'/titan-engine-dev/',preview:{host:'127.0.0.1',port:8096,strictPort:true}})
  browser=await chromium.launch({channel:'chrome',headless:true})
  const page=await browser.newPage({viewport:{width:1280,height:720},deviceScaleFactor:1})
  cdp=await page.context().newCDPSession(page);await cdp.send('Performance.enable')
  const pending=new Set()
  page.on('pageerror',error=>report.errors.push(error.stack||error.message))
  page.on('console',message=>{
    if(message.type()==='error') report.errors.push(message.text())
    if(message.type()==='warning') report.warnings.push(message.text())
  })
  page.on('request',request=>{
    pending.add(request)
    const u=new URL(request.url()),route=u.pathname.replace(/^\/titan-engine-dev(?=\/)/,'')
    report.requests.push({origin:u.origin,path:u.pathname,type:request.resourceType()})
    if(/^\/(?:src|@vite|@id|tests)\//.test(route)) report.sourceModuleRequests.push(u.origin+u.pathname)
  })
  page.on('requestfinished',request=>pending.delete(request))
  page.on('requestfailed',request=>{
    pending.delete(request)
    const u=new URL(request.url()),failure={origin:u.origin,path:u.pathname,error:request.failure()?.errorText}
    if(/ERR_ABORTED/.test(failure.error||'')) report.abortedRequests.push(failure)
    else report.assetFailures.push(failure)
  })
  page.on('response',response=>{
    const u=new URL(response.url())
    if(response.status()>=400) report.assetFailures.push({origin:u.origin,path:u.pathname,status:response.status()})
    if(u.origin==='https://storage.yandexcloud.net'&&response.ok()) report.cloudResponses++
  })
  await page.addInitScript(()=>{
    const proto=HTMLCanvasElement.prototype,descriptor=Object.getOwnPropertyDescriptor(proto,'getContext'),original=proto.getContext
    const seen=new WeakSet();let contexts=0
    proto.getContext=function(...args){
      const context=original.apply(this,args)
      if(context&&/^(webgl|webgl2|experimental-webgl)$/.test(args[0])&&!seen.has(this)){seen.add(this);contexts++}
      return context
    }
    window.__memorySoakContexts={count:()=>contexts,restore:()=>{
      Object.defineProperty(proto,'getContext',descriptor)
      const after=Object.getOwnPropertyDescriptor(proto,'getContext')
      if(['value','get','set','writable','configurable','enumerable'].some(k=>after[k]!==descriptor[k]))throw Error('Context hook restoration failed')
      return {contexts,restored:true}
    }}
  })
  await page.goto('http://127.0.0.1:8096/titan-engine-dev/')
  await page.getByRole('button',{name:/^Run /}).first().waitFor()
  await page.addScriptTag({path:root+'gpu-draws-2026-10-27.browser.js',type:'module'})
  await page.evaluate(c=>window.__productionFrame.connect(c.entryUrl,c.runtimeUrl),report.connection)
  await page.addScriptTag({path:root+name+'.browser.js',type:'module'})
  await page.evaluate(url=>window.__connectMemorySoak(url).then(()=>true),report.connection.runtimeUrl)
  const check=()=>{for(const key of ['errors','warnings','assetFailures','sourceModuleRequests']) assert.deepEqual(report[key],[],key)}
  const sample=async()=>{
    const startedAt=new Date().toISOString()
    await cdp.send('HeapProfiler.collectGarbage')
    const heap=await cdp.send('Runtime.getHeapUsage'),metrics=await cdp.send('Performance.getMetrics'),dom=await cdp.send('Memory.getDOMCounters')
    for(const key of ['usedSize','totalSize','embedderHeapUsedSize','backingStorageSize']) assert.ok(Number.isFinite(heap[key])&&heap[key]>=0,key)
    return {startedAt,finishedAt:new Date().toISOString(),heap,metrics:metrics.metrics,dom,pendingRequests:pending.size,snapshot:await page.evaluate(()=>window.__memorySoak.snapshot())}
  }
  for(let round=0;round<=options.rounds;round++) for(const [id,actor] of [[13,135],[12,127]]) {
    const phase=round?'measured':'warmup',requestsBefore=report.requests.length,cloudBefore=report.cloudResponses
    console.log('MEMORY_SOAK_START',JSON.stringify({phase,round,id,at:new Date().toISOString()}))
    const selected=await page.evaluate(id=>window.__productionFrame.selectScenario(id),id)
    assert.doesNotMatch(selected.renderer,/SwiftShader|software|llvmpipe/i)
    const view=await page.evaluate(actor=>window.__productionFrame.setView(actor),actor)
    await page.evaluate(n=>window.__productionFrame.settle(n),options.settleFrames)
    const activeBefore=await sample()
    const exercise=await page.evaluate(o=>window.__memorySoak.exercise(o),{durationMs:round?options.dwellMs:options.warmupMs,periodMs:options.periodMs,spanTu:options.spanTu})
    const activeAfter=await sample()
    const menu=await page.evaluate(()=>window.__productionFrame.menu())
    await page.waitForTimeout(options.menuIdleMs)
    const collectedMenu=await sample()
    const row={phase,round,id,selected,view,activeBefore,exercise,activeAfter,menu,collectedMenu,
      requests:report.requests.length-requestsBefore,cloudResponses:report.cloudResponses-cloudBefore}
    report.rows.push(row);save()
    const m=collectedMenu.snapshot
    assert.deepEqual(m.memory,{geometries:1,textures:0});assert.equal(m.programs,0)
    assert.equal(m.canvases,1);assert.equal(m.createdWebGLContexts,1);assert.equal(m.volumes,0)
    assert.equal(m.pendingBakes,0);assert.equal(m.bakeBytes,0);assert.deepEqual(m.streamers,[])
    assert.equal(menu.scenario,null);check()
    console.log('MEMORY_SOAK_ROW',JSON.stringify({phase,round,id,frames:exercise.frameCount,elapsedMs:exercise.elapsedMs,heap:collectedMenu.heap,
      dom:collectedMenu.dom,menu:m.memory,programs:m.programs,activeHeap:activeAfter.heap,requests:row.requests,cloud:row.cloudResponses}))
  }
  await page.waitForTimeout(10000)
  report.finalIdle=await sample()
  report.restoration=await page.evaluate(()=>window.__memorySoak.restore())
  check();verifyInputs();assert.ok(report.cloudResponses>0)
  report.outcome='completed'
} catch(error) {report.failure=error.stack||error.message;console.error(error);process.exitCode=1}
finally {report.finishedAt=new Date().toISOString();save();await cdp?.detach();await browser?.close();if(server)await new Promise(resolve=>server.httpServer.close(resolve))}

