// External diagnostic: imports only the already-built application modules.
// No source-module imports, alternative renderer, production patch or render setting changes.
const stats = values => {
  const sorted = values.slice().sort((a, b) => a - b)
  if (!sorted.length) return { count: 0 }
  const quantile = q => sorted[Math.ceil(sorted.length * q) - 1]
  return { count: sorted.length, p50: quantile(.5), p95: quantile(.95), p99: quantile(.99), max: sorted.at(-1), mean: values.reduce((a, b) => a + b, 0) / values.length }
}
const nextFrame = () => new Promise(resolve => requestAnimationFrame(resolve))
const preserve = (object, key) => {
  const descriptor = Object.getOwnPropertyDescriptor(object, key)
  return () => {
    if (descriptor) Object.defineProperty(object, key, descriptor); else delete object[key]
    const restored = Object.getOwnPropertyDescriptor(object, key)
    if (!!restored !== !!descriptor || (descriptor && ['value', 'get', 'set', 'writable', 'configurable', 'enumerable'].some(field => descriptor[field] !== restored[field]))) throw Error(`Descriptor restoration failed: ${key}`)
  }
}
let store, scenarios, runtimeModule, connection
const runtime = () => {
  const value = runtimeModule.getInitializedSimulationRuntime()
  if (!value) throw Error('Production runtime not initialized')
  return value
}
const get = name => {
  const container = runtime().container
  const keys = [...container.bindings.keys()].filter(key => typeof key === 'object' && key.name === name)
  if (keys.length !== 1) throw Error(`Ambiguous/missing production token: ${name}`)
  return container.get(keys[0])
}
const label = object => {
  const names = []
  for (let item = object; item; item = item.parent) names.push(`${item.name || item.type}${item.model ? ':' + item.model.getAttribute('id') : ''}`)
  return names.reverse().join('/')
}

async function connect(entryUrl, runtimeUrl) {
  const entry = await import(entryUrl)
  const stores = Object.entries(entry).filter(([, value]) => value && typeof value === 'object' && typeof value.setScenario === 'function' && 'appLoadingStatus' in value)
  const lists = Object.entries(entry).filter(([, value]) => Array.isArray(value) && value.some(item => item?.id === 13 && Array.isArray(item.defaultCameraPosition)) && value.some(item => item?.id === 12))
  if (stores.length !== 1 || lists.length !== 1) throw Error('Production entry export identification failed')
  store = stores[0][1]; scenarios = lists[0][1]
  runtimeModule = await import(runtimeUrl)
  if (typeof runtimeModule.getInitializedSimulationRuntime !== 'function') throw Error('Production runtime export missing')
  connection = { entryUrl, runtimeUrl, storeExport: stores[0][0], scenariosExport: lists[0][0] }
  return connection
}
async function selectScenario(id) {
  const selected = scenarios.find(item => item.id === id)
  if (!selected) throw Error(`Scenario missing: ${id}`)
  const start = performance.now()
  await store.setScenario(selected)
  if (store.scenario?.id !== id || store.appLoadingStatus) throw Error('Scenario startup failed')
  return { id, name: selected.name, startupMs: performance.now() - start, ...snapshot() }
}
async function menu() {
  await store.setScenario(null)
  await nextFrame(); await nextFrame()
  return snapshot()
}
function snapshot() {
  const renderer = get('Renderer'), gl = renderer.getContext(), debug = gl.getExtension('WEBGL_debug_renderer_info')
  const scene = get('Scene'), camera = get('Camera'), queue = get('NebulaBakeQueue')
  const streamers = []
  scene.traverse(object => {
    if (object.pool?.commitUpdates && object.cascades?.managers) streamers.push({ label: label(object), visible: object.visible, info: object.getDebugInfo() })
  })
  return { scenario: store.scenario?.id ?? null, renderer: gl.getParameter(debug ? debug.UNMASKED_RENDERER_WEBGL : gl.RENDERER),
    userAgent: navigator.userAgent, viewport: [innerWidth, innerHeight], dpr: devicePixelRatio,
    pendingBakes: queue.pendingCount, bakeBytes: queue.allocatedBytes,
    camera: camera.position.toArray(), orientation: camera.quaternion.toArray(), streamers,
    memory: { ...renderer.info.memory }, programs: renderer.info.programs.length,
    heapBytes: performance.memory?.usedJSHeapSize ?? null,
    volumes: get('DepthVolumeRegistry').volumes().map(volume => ({ label: label(volume), visible: volume.visible, resolutionScale: volume.resolutionScale,
      densityReady: volume.material?.uniforms?.uDensityReady?.value, lod: volume.material?.uniforms?.uLodBlend?.value })) }
}
function setView(actorId) {
  const scene = get('Scene'), camera = get('Camera')
  let target, belt
  scene.traverse(object => { if (!target && object.model?.getAttribute('id') === actorId) target = object })
  if (!target) throw Error('Belt actor missing')
  target.traverse(object => { if (object.name === 'AsteroidBelt' && Number.isFinite(object.innerRadiusTu) && Number.isFinite(object.outerRadiusTu)) belt = object })
  if (!belt) throw Error('Production belt missing')
  const center = target.getWorldPosition(camera.position.clone())
  get('CameraController').stopFollowing()
  camera.position.set((belt.innerRadiusTu + belt.outerRadiusTu) / 2, 0, 0).applyMatrix4(belt.matrixWorld)
  camera.lookAt(center); camera.updateMatrixWorld(true)
  get('CameraCollision').reset()
  return { actorId, center: center.toArray(), camera: camera.position.toArray(), orientation: camera.quaternion.toArray(), name: target.model.getAttribute('name') }
}
async function settle(frames = 64) {
  for (let i = 0; i < frames; i++) await nextFrame()
  if (get('NebulaBakeQueue').pendingCount !== 0) throw Error('Bake work remains after warmup')
}

class Queries {
  constructor(gl) {
    this.gl = gl; this.pending = []; this.active = false
    this.ext = gl.getExtension('EXT_disjoint_timer_query_webgl2')
    if (!this.ext || !(gl.getQuery(this.ext.TIME_ELAPSED_EXT, this.ext.QUERY_COUNTER_BITS_EXT) > 0)) throw Error('Native GPU timer unavailable')
    gl.getParameter(this.ext.GPU_DISJOINT_EXT)
  }
  measure(key, frame, callback) {
    if (this.active) throw Error('Nested GPU query')
    const gl = this.gl, query = gl.createQuery()
    if (!query) throw Error('GPU query allocation failed')
    gl.beginQuery(this.ext.TIME_ELAPSED_EXT, query); this.active = true
    try { return callback() }
    finally { gl.endQuery(this.ext.TIME_ELAPSED_EXT); this.active = false; this.pending.push({ query, key, frame }) }
  }
  async finish() {
    const samples = [], gl = this.gl, start = performance.now()
    // Never poll in a measured frame: getParameter may synchronize with the GPU.
    while (this.pending.length) {
      await new Promise(resolve => setTimeout(resolve, 16))
      if (gl.isContextLost() || gl.getParameter(this.ext.GPU_DISJOINT_EXT)) throw Error('GPU context lost/disjoint; discard run')
      while (this.pending.length && gl.getQueryParameter(this.pending[0].query, gl.QUERY_RESULT_AVAILABLE)) {
        const { query, key, frame } = this.pending.shift()
        const ms = gl.getQueryParameter(query, gl.QUERY_RESULT) / 1e6
        gl.deleteQuery(query)
        if (!Number.isFinite(ms) || ms <= 0) throw Error('Invalid GPU sample')
        samples.push({ key, frame, ms })
      }
      if (performance.now() - start > 60000) throw Error('GPU results timeout')
    }
    return samples
  }
  dispose() { for (const { query } of this.pending) this.gl.deleteQuery(query); this.pending = [] }
}

async function measure({ mode = 'plain', motion = false, frames = 240 }) {
  if (!['plain', 'gpu-frame', 'passes', 'volumes', 'cpu', 'attribution'].includes(mode)) throw Error('Unknown mode')
  const engine = get('Engine'), camera = get('Camera'), renderer = get('Renderer'), gl = renderer.getContext(), pp = get('Postprocessing')
  const origin = camera.position.clone(), orientation = camera.quaternion.clone(), direction = camera.position.clone().set(1, 0, 0).applyQuaternion(orientation)
  const initial = snapshot(), oldFrame = engine.renderFrame, restoreFrame = preserve(engine, 'renderFrame'), undo = [], cpu = {}, cpuCalls = {}, draws = {}
  const intervals = [], wholeCpu = [], starts = [], positions = [], queries = ['gpu-frame', 'passes', 'volumes', 'attribution'].includes(mode) ? new Queries(gl) : null
  const blits = {}, materials = {}, targets = {}, workload = {}, targetRefs = new Map(), restoration = { complete: false }
  let frame = -1, measured = 0, failure = null, active = true
  const wrap = (object, method, name, gpu = false) => {
    const original = object[method]
    const restore = preserve(object, method)
    if (typeof original !== 'function') throw Error(`Missing measured method: ${name}`)
    object[method] = function (...args) {
      if (frame < 0) return original.apply(this, args)
      const key = typeof name === 'function' ? name(args) : name
      const start = performance.now()
      try { return gpu ? queries.measure(key, frame, () => original.apply(this, args)) : original.apply(this, args) }
      finally { (cpu[key] ??= Array(frames).fill(0))[frame] += performance.now() - start; (cpuCalls[key] ??= Array(frames).fill(0))[frame]++ }
    }
    undo.push(restore)
  }
  try {
    if (mode === 'attribution') {
      let currentPass = 'outside', readFramebuffer = gl.getParameter(gl.READ_FRAMEBUFFER_BINDING), drawFramebuffer = gl.getParameter(gl.DRAW_FRAMEBUFFER_BINDING)
      const framebufferIds = new Map(), targetIds = new Map()
      const framebufferId = value => {
        if (value === null) return 'default'
        if (!framebufferIds.has(value)) framebufferIds.set(value, 'fb' + framebufferIds.size)
        return framebufferIds.get(value)
      }
      const targetId = target => {
        if (!target) return 'screen'
        if (!targetIds.has(target)) {
          const id = 'rt' + targetIds.size
          targetIds.set(target, id); targetRefs.set(id, target)
          targets[id] = { name: target.texture.name, width: target.width, height: target.height, samplesRequested: target.samples,
            depthBuffer: target.depthBuffer, stencilBuffer: target.stencilBuffer, resolveDepthBuffer: target.resolveDepthBuffer,
            type: target.texture.type, format: target.texture.format, textures: target.textures.length }
        }
        return targetIds.get(target)
      }
