          vertexShader: material.vertexShader, fragmentShader: material.fragmentShader, transparent: material.transparent,
          depthWrite: material.depthWrite, depthTest: material.depthTest, blending: material.blending, side: material.side }
        if (!draws[key]) draws[key] = { pass: currentPass, target, object: label(object), objectName: object.name, material: material.id,
          instanced: !!object.isInstancedMesh, geometry: geometry.type, indices: geometry.index?.count ?? 0, vertices: geometry.attributes.position?.count ?? 0 }
        const sourceCount = geometry.index?.count ?? geometry.attributes.position?.count ?? 0
        const start = Math.max(geometry.drawRange.start, group?.start ?? 0)
        const end = Math.min(sourceCount, geometry.drawRange.start + geometry.drawRange.count, group ? group.start + group.count : Infinity)
        const submitted = workload[key] ??= { instances: Array(frames).fill(0), elements: Array(frames).fill(0), calls: Array(frames).fill(0) }
        const instances = object.isInstancedMesh ? object.count : geometry.isInstancedBufferGeometry ? Math.min(geometry.instanceCount, geometry._maxInstanceCount ?? Infinity) : 1
        if (!Number.isFinite(instances) || instances < 0) throw Error('Invalid submitted instance count')
        submitted.instances[frame] += instances; submitted.elements[frame] += Math.max(0, end - start) * instances; submitted.calls[frame]++
        return queries.measure(key, frame, () => originalDraw.apply(this, args))
      }
      undo.push(restoreDraw)
    }
    if (mode === 'passes') for (const [i, pass] of pp.composer.passes.entries()) wrap(pass, 'render', `${i}:${pass.name}`, true)
    if (mode === 'cpu') {
      for (const [name, methods] of [['SceneManager', ['update', 'updateView', 'updateMarkers']], ['SceneObserver', ['tick']], ['CameraCollision', ['resolve']], ['NebulaBakeQueue', ['pumpFrame']], ['AsteroidImpostorLibrary', ['pumpFrame']], ['Postprocessing', ['render']], ['LabelRenderer', ['render']]]) {
        const service = get(name)
        for (const method of methods) wrap(service, method, `${name}.${method}`)
      }
      const pools = new Set(), managers = new Set(), visibilityPrototypes = new Set()
      get('Scene').traverse(object => {
        if (object.pool?.commitUpdates && object.cascades?.managers) {
          pools.add(object.pool)
          for (const manager of object.cascades.managers) managers.add(manager)
          for (const stream of object.pool.streams) if (stream.visibility) visibilityPrototypes.add(Object.getPrototypeOf(stream.visibility))
        }
      })
      if (!pools.size || !managers.size || !visibilityPrototypes.size) throw Error('Missing CPU instrumentation targets')
      for (const pool of pools) { wrap(pool, 'commitUpdates', 'pool.commit'); wrap(pool, 'updateVisibility', 'pool.visibility') }
      for (const manager of managers) { wrap(manager, 'update', 'sectors.update'); wrap(manager, 'allocateForLOD', 'sectors.allocate') }
      for (const proto of visibilityPrototypes) {
        wrap(proto, 'update', 'visibility.geometry'); wrap(proto, 'updateImpostors', 'visibility.impostors'); wrap(proto, 'copyVisible', 'visibility.copy')
      }
      wrap(gl, 'bufferSubData', 'gl.bufferSubData')
      wrap(gl, 'getParameter', args => 'gl.getParameter:' + args[0].toString(16))
    }
    if (mode === 'volumes') {
      let inPass = false, volumeName = 'pass'
      const pass = pp.composer.passes.find(item => item.name === 'DepthVolumePass')
      const passRender = pass.render, scaledRender = pass.scaled.render, direct = renderer.renderBufferDirect
      const restorePass = preserve(pass, 'render'), restoreScaled = preserve(pass.scaled, 'render'), restoreDirect = preserve(renderer, 'renderBufferDirect')
      pass.render = function (...args) { inPass = true; try { return passRender.apply(this, args) } finally { inPass = false } }
      pass.scaled.render = function (...args) { volumeName = label(args[3]); try { return scaledRender.apply(this, args) } finally { volumeName = 'pass' } }
