    })
    engine.stop()
    if (failure) throw failure
    if (measured !== frames || wholeCpu.length !== frames || intervals.length !== frames - 1) throw Error('Incomplete frame window')
    const gpu = queries ? await queries.finish() : []
    if (mode === 'attribution') {
      // Inspect hardware samples only after the window and query collection. No sync reads inside measured frames.
      const previousRenderbuffer = gl.getParameter(gl.RENDERBUFFER_BINDING)
      try {
        for (const [id, target] of targetRefs) {
