      summary: { intervals: stats(intervals), wholeCpu: stats(wholeCpu), cpu: Object.fromEntries(Object.entries(cpu).map(([key, value]) => [key, stats(value)])),
        gpu: Object.fromEntries(Object.entries(gpuPerFrame).map(([key, value]) => [key, stats(value)])) },
      caveat: mode === 'plain' ? 'Actual unchanged production bundle. Only renderFrame wall-time/entry timestamps and frame-indexed camera trajectory are instrumented; no GPU queries, per-component wrappers or CPU profiler. Headless/native cadence is not a cross-device FPS guarantee.' :
        'Separate diagnostic window on the same production bundle; instrumentation overhead present. GPU polling is deferred until after stopping the engine. CPU wall durations can include GPU/driver stalls; component timings can be nested. Per-volume draw queries exclude surrounding renderer work and resolves. Do not sum medians or compare these intervals as FPS against plain windows.' }
  } finally {
