import {readFileSync,writeFileSync,existsSync} from 'node:fs'
import {createHash} from 'node:crypto'
import {gzipSync,gunzipSync} from 'node:zlib'
import {execFileSync} from 'node:child_process'
import assert from 'node:assert/strict'
const root='benchmark-results/heavy-scenes/',name='production-memory-soak-2026-10-28'
const base='83976aef4e5110bad3f5f5b3914c67a6ea5a841f',codeBase='c00a4de416befd402c3587ccb31e7f2a24e05a1d'
const output='docs/benchmarks/'+name+'.json',reviewPath=root+'production-memory-soak-review-2026-10-28.json'
const sha=b=>createHash('sha256').update(b).digest('hex')
const read=p=>{const b=readFileSync(p);return b[0]===255&&b[1]===254?b.subarray(2).toString('utf16le'):b.toString('utf8').replace(/^\uFEFF/,'')}
const json=p=>JSON.parse(read(p))
const pack=p=>{const b=readFileSync(p);return {path:p,bytes:b.length,sha256:sha(b),encoding:'gzip+base64',gzipBase64:gzipSync(b,{level:9}).toString('base64')}}
const unpack=r=>{const b=gunzipSync(Buffer.from(r.gzipBase64,'base64'));assert.equal(b.length,r.bytes);assert.equal(sha(b),r.sha256);return JSON.parse(b.toString('utf8'))}
const applicationPaths=['src/core/Engine.ts','tests/EngineDispose.spec.ts','tests/EngineFrame.spec.ts']
const baselineSourcePath=root+'production-memory-soak-baseline-sources-2026-10-28.json'
const baselineSourceSnapshot=json(baselineSourcePath)
const baselineBytes=p=>{
  if(!/^(src|tests)\//.test(p))return readFileSync(p)
  const text=baselineSourceSnapshot[p]
  assert.equal(typeof text,'string',p)
  assert.equal(text.replace(/\r\n/g,'\n'),execFileSync('git',['show',base+':'+p],{encoding:'utf8'}).replace(/\r\n/g,'\n'),p)
  return Buffer.from(text)
}
const applicationDiff=()=>execFileSync('git',['diff',base,'--',...applicationPaths],{encoding:'utf8'})
function stats(values){
  assert.ok(values.length);const a=[...values].sort((a,b)=>a-b),q=p=>a[Math.ceil(a.length*p)-1]
  return {count:a.length,p50:q(.5),p95:q(.95),p99:q(.99),max:a.at(-1),mean:values.reduce((a,b)=>a+b,0)/a.length}
}
function trend(values){
  assert.ok(values.length);const n=values.length,xMean=(n-1)/2,yMean=values.reduce((a,b)=>a+b,0)/n
  const denominator=values.reduce((sum,_,i)=>sum+(i-xMean)**2,0)
  return {count:n,first:values[0],last:values.at(-1),delta:values.at(-1)-values[0],min:Math.min(...values),max:Math.max(...values),
    range:Math.max(...values)-Math.min(...values),slopePerVisit:denominator?values.reduce((sum,value,i)=>sum+(i-xMean)*(value-yMean),0)/denominator:null,values}
}
function menuGate(m){
  assert.deepEqual(m.memory,{geometries:1,textures:0});assert.equal(m.programs,0)
  assert.equal(m.sceneObjects,1);assert.equal(m.meshes,0);assert.equal(m.instancedMeshes,0)
  assert.equal(m.canvases,1);assert.equal(m.createdWebGLContexts,1);assert.equal(m.volumes,0)
  assert.equal(m.pendingBakes,0);assert.equal(m.bakeBytes,0);assert.deepEqual(m.streamers,[])
}
function sample(s){
  assert.ok(Date.parse(s.finishedAt)>=Date.parse(s.startedAt))
  for(const k of ['usedSize','totalSize','embedderHeapUsedSize','backingStorageSize']) assert.ok(Number.isFinite(s.heap[k])&&s.heap[k]>=0,k)
  assert.ok(s.heap.usedSize<=s.heap.totalSize)
  for(const k of ['documents','nodes','jsEventListeners']) assert.ok(Number.isInteger(s.dom[k])&&s.dom[k]>0,k)
  assert.ok(s.metrics.some(x=>x.name==='JSHeapUsedSize'&&x.value>0))
  assert.ok(Number.isInteger(s.pendingRequests)&&s.pendingRequests>=0)
}
function verifyReport(r,smoke){
  assert.equal(r.outcome,'completed');assert.equal(r.base,base);assert.equal(r.codeBase,codeBase)
  assert.deepEqual(r.options,{smoke,rounds:smoke?0:6,warmupMs:smoke?5000:15000,dwellMs:60000,periodMs:60000,spanTu:2,menuIdleMs:1000,settleFrames:64})
  assert.equal(r.rows.length,smoke?2:14);assert.ok(r.cloudResponses>0)
  assert.deepEqual(r.restoration,{contexts:1,restored:true})
  for(const k of ['errors','warnings','assetFailures','abortedRequests','sourceModuleRequests'])assert.deepEqual(r[k],[],k)
  assert.equal(r.buildFiles.length,32)
  for(const f of r.buildFiles){const b=readFileSync(r.frozenBundle+'/'+f.path);assert.equal(b.length,f.bytes);assert.equal(sha(b),f.sha256)}
  for(const [p,h] of Object.entries({...r.sourceHashes,...Object.fromEntries(Object.entries(r.buildInputHashes).filter(([p])=>p.startsWith('src/')||p.startsWith('tests/')))}))assert.equal(sha(baselineBytes(p)),h,p)
