    assert.equal(request.origin,'http://127.0.0.1:8096');assert.ok(r.buildFiles.some(f=>request.path==='/titan-engine-dev/'+f.path),request.path)
  }
  assert.deepEqual(r.rows.map(x=>[x.round,x.id]),Array.from({length:smoke?1:7},(_,i)=>[13,12].map(id=>[i,id])).flat())
  let lastFrame=-1
  for(const row of r.rows){
    assert.equal(row.phase,row.round?'measured':'warmup');assert.equal(row.id,row.selected.id)
    assert.doesNotMatch(row.selected.renderer,/SwiftShader|software|llvmpipe/i)
    assert.deepEqual(row.selected.viewport,[1280,720]);assert.equal(row.selected.dpr,1)
    sample(row.activeBefore);sample(row.activeAfter);sample(row.collectedMenu);menuGate(row.collectedMenu.snapshot)
    assert.equal(row.menu.scenario,null);assert.equal(row.menu.pendingBakes,0)
    assert.ok(row.activeBefore.snapshot.instancedMeshes>0);assert.ok(row.activeAfter.snapshot.streamers.length>0)
    const e=row.exercise,n=e.frameCount
