    assert.equal(e.restoration,true);assert.equal(e.starts.length,n);assert.equal(e.cpu.length,n)
    assert.deepEqual(e.intervals,e.starts.slice(1).map((x,i)=>x-e.starts[i]));assert.ok(e.intervals.every(x=>x>0));assert.ok(e.cpu.every(x=>Number.isFinite(x)&&x>=0))
    assert.deepEqual(e.summary,{intervals:stats(e.intervals),cpu:stats(e.cpu)})
    assert.ok(e.elapsedMs>=e.durationMs);assert.ok(Math.abs(e.elapsedMs-(e.starts.at(-1)+e.cpu.at(-1)-e.starts[0]))<1e-5)
    assert.ok(e.initial.frame>=row.activeBefore.snapshot.frame);assert.ok(e.final.frame>e.initial.frame)
    assert.ok(row.collectedMenu.snapshot.frame>lastFrame);lastFrame=row.collectedMenu.snapshot.frame
    assert.equal(e.samples.length,e.poses.length);assert.equal(e.samples[0].frame,0);assert.equal(e.samples.at(-1).frame,n-1)
    assert.ok(e.samples.at(-1).elapsed>=e.durationMs)
    for(const [i,s] of e.samples.entries()){
      assert.equal(s.frame,e.poses[i].frame);assert.ok(s.frame>=0&&s.frame<n)
      assert.ok(Math.abs(s.elapsed-(e.starts[s.frame]-e.starts[0]))<1e-5)
      assert.equal(s.snapshot.createdWebGLContexts,1);assert.equal(s.snapshot.canvases,1)
      assert.ok(s.snapshot.streamers.some(x=>x.info.activeSectors>0))
      const distance=Math.hypot(...e.poses[i].position.map((x,j)=>x-e.initial.camera[j]))
      assert.ok(Math.abs(distance-Math.abs(Math.sin(Math.min(s.elapsed,e.durationMs)/e.periodMs*Math.PI*2)*2))<1e-5)
    }
    for(const k of ['camera','orientation'])assert.deepEqual(row.activeAfter.snapshot[k],e.initial[k])
  }
  sample(r.finalIdle);menuGate(r.finalIdle.snapshot)
  assert.equal(r.finalIdle.snapshot.frame,lastFrame,'No render after final menu')
}
function analyze(r){
  const measured=r.rows.filter(x=>x.phase==='measured')
  const fields=['usedSize','totalSize','embedderHeapUsedSize','backingStorageSize']
  return {wallSeconds:(Date.parse(r.finishedAt)-Date.parse(r.startedAt))/1000,
    warmupVisits:r.rows.length-measured.length,measuredVisits:measured.length,measuredFrameCount:measured.reduce((sum,x)=>sum+x.exercise.frameCount,0),
    measuredRequestedMs:measured.reduce((sum,x)=>sum+x.exercise.durationMs,0),measuredActualMs:measured.reduce((sum,x)=>sum+x.exercise.elapsedMs,0),
    byScenario:[13,12].map(id=>{
      const rows=measured.filter(x=>x.id===id)
      return {id,visits:rows.length,
        menuHeap:Object.fromEntries(fields.map(k=>[k,trend(rows.map(x=>x.collectedMenu.heap[k]))])),
        activeAfterHeap:Object.fromEntries(fields.map(k=>[k,trend(rows.map(x=>x.activeAfter.heap[k]))])),
        dom:Object.fromEntries(['documents','nodes','jsEventListeners'].map(k=>[k,trend(rows.map(x=>x.collectedMenu.dom[k]))])),
        pendingRequests:trend(rows.map(x=>x.collectedMenu.pendingRequests)),
        frameIntervals:stats(rows.flatMap(x=>x.exercise.intervals)),cpuFrameWall:stats(rows.flatMap(x=>x.exercise.cpu)),
        cpuOver100ms:rows.reduce((n,x)=>n+x.exercise.cpu.filter(t=>t>100).length,0),intervalsOver250ms:rows.reduce((n,x)=>n+x.exercise.intervals.filter(t=>t>250).length,0),
        rows:rows.map(x=>({round:x.round,frames:x.exercise.frameCount,elapsedMs:x.exercise.elapsedMs,heap:x.collectedMenu.heap,pendingRequests:x.collectedMenu.pendingRequests,
          intervals:x.exercise.summary.intervals,cpu:x.exercise.summary.cpu,requests:x.requests,cloudResponses:x.cloudResponses}))}
    }),finalIdle:r.finalIdle}
}
function verify(archive){
