  for(const f of archive.provenance){const b=readFileSync(f.path);assert.equal(b.length,f.bytes);assert.equal(sha(b),f.sha256,f.path)}
  assert.deepEqual(execFileSync('git',['diff',base,'--name-only','--','src','tests','package.json','package-lock.json','vite.config.ts'],{encoding:'utf8'}).trim().split(/\r?\n/).sort(),[...applicationPaths].sort())
