import {preview} from 'vite'
import {chromium} from '@playwright/test'
import {readFileSync,writeFileSync,openSync,writeSync,closeSync} from 'node:fs'
import {createHash} from 'node:crypto'
import {execFileSync} from 'node:child_process'
import assert from 'node:assert/strict'
const root='benchmark-results/heavy-scenes/',name='production-memory-retainers-2026-10-28'
const base='83976aef4e5110bad3f5f5b3914c67a6ea5a841f',sha=b=>createHash('sha256').update(b).digest('hex')
assert.equal(execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),base)
const previous=JSON.parse(readFileSync(root+'production-memory-soak-2026-10-28-smoke.json','utf8'))
assert.equal(previous.outcome,'completed')
for(const f of previous.buildFiles)assert.equal(sha(readFileSync(previous.frozenBundle+'/'+f.path)),f.sha256)
const paths=[root+'run-'+name+'.mjs',root+'production-memory-soak-2026-10-28.browser.js',root+'gpu-draws-2026-10-27.browser.js']
const report={base,startedAt:new Date().toISOString(),frozenBundle:previous.frozenBundle,buildFiles:previous.buildFiles,connection:previous.connection,
  sourceHashes:Object.fromEntries(paths.map(p=>[p,sha(readFileSync(p))])),samples:[],snapshots:[],errors:[],warnings:[],assetFailures:[],aborted:[],cloudResponses:0,outcome:'failed',
  scope:'Follow-up for small collected JS heap growth. Same page production scene warmup, idle diagnostic controls, four15second scene visits, two heap snapshots. CDP sampling observes retained allocations; this is not a new performance benchmark.'}
const output=root+name+'.json';writeFileSync(output,JSON.stringify(report,null,2),{flag:'wx'})
const save=()=>writeFileSync(output,JSON.stringify(report,null,2))
let server,browser,cdp
try{
  server=await preview({build:{outDir:report.frozenBundle},base:'/titan-engine-dev/',preview:{host:'127.0.0.1',port:8096,strictPort:true}})
  browser=await chromium.launch({channel:'chrome',headless:true})
  const page=await browser.newPage({viewport:{width:1280,height:720},deviceScaleFactor:1})
  cdp=await page.context().newCDPSession(page);await cdp.send('Performance.enable')
  page.on('pageerror',e=>report.errors.push(e.stack||e.message))
  page.on('console',m=>{if(m.type()==='error')report.errors.push(m.text());if(m.type()==='warning')report.warnings.push(m.text())})
  const pending=new Map()
  page.on('request',r=>{const u=new URL(r.url());pending.set(r,{origin:u.origin,path:u.pathname,type:r.resourceType()})})
  page.on('requestfinished',r=>pending.delete(r))
  page.on('requestfailed',r=>{const detail={...pending.get(r),error:r.failure()?.errorText};pending.delete(r);if(/ERR_ABORTED/.test(detail.error||''))report.aborted.push(detail);else report.assetFailures.push(detail)})
  page.on('response',r=>{const u=new URL(r.url());if(r.status()>=400)report.assetFailures.push({origin:u.origin,path:u.pathname,status:r.status()});if(u.origin==='https://storage.yandexcloud.net'&&r.ok())report.cloudResponses++})
  await page.addInitScript(()=>{
    const proto=HTMLCanvasElement.prototype,descriptor=Object.getOwnPropertyDescriptor(proto,'getContext'),original=proto.getContext
    const seen=new WeakSet();let contexts=0
    proto.getContext=function(...args){const context=original.apply(this,args);if(context&&/^(webgl|webgl2)$/.test(args[0])&&!seen.has(this)){seen.add(this);contexts++}return context}
    window.__memorySoakContexts={count:()=>contexts,restore:()=>{Object.defineProperty(proto,'getContext',descriptor);return {contexts,restored:proto.getContext===original}}}
  })
  await page.goto('http://127.0.0.1:8096/titan-engine-dev/')
  await page.getByRole('button',{name:/^Run /}).first().waitFor()
  await page.addScriptTag({path:root+'gpu-draws-2026-10-27.browser.js',type:'module'})
  await page.evaluate(c=>window.__productionFrame.connect(c.entryUrl,c.runtimeUrl),report.connection)
  await page.addScriptTag({path:root+'production-memory-soak-2026-10-28.browser.js',type:'module'})
  await page.evaluate(u=>window.__connectMemorySoak(u).then(()=>true),report.connection.runtimeUrl)
  const collect=async(label)=>{
    await cdp.send('HeapProfiler.collectGarbage')
    const heap=await cdp.send('Runtime.getHeapUsage'),dom=await cdp.send('Memory.getDOMCounters')
    const snapshot=await page.evaluate(()=>window.__memorySoak.snapshot())
    const value={label,at:new Date().toISOString(),heap,dom,snapshot,pending:[...pending.values()]}
    report.samples.push(value);save();console.log('RETAINER_MEMORY',JSON.stringify({label,heap,pending:value.pending.length}));return value
  }
  const visit=async(id,phase)=>{
    const selected=await page.evaluate(id=>window.__productionFrame.selectScenario(id),id)
    assert.doesNotMatch(selected.renderer,/SwiftShader|software|llvmpipe/i)
    await page.evaluate(actor=>window.__productionFrame.setView(actor),id===13?135:127)
    await page.evaluate(()=>window.__productionFrame.settle(64))
    await page.evaluate(()=>window.__memorySoak.exercise({durationMs:15000}))
    await page.evaluate(()=>window.__productionFrame.menu())
    await page.waitForTimeout(1000)
    const row=await collect(phase+'-'+id)
    assert.deepEqual(row.snapshot.memory,{geometries:1,textures:0});assert.equal(row.snapshot.programs,0)
    assert.equal(row.snapshot.sceneObjects,1)
  }
  const snapshot=async(label)=>{
    await cdp.send('HeapProfiler.collectGarbage')
    const path=root+name+'-'+label+'.heapsnapshot',fd=openSync(path,'wx')
    const listener=event=>writeSync(fd,event.chunk)
    cdp.on('HeapProfiler.addHeapSnapshotChunk',listener)
    try{await cdp.send('HeapProfiler.takeHeapSnapshot',{reportProgress:false})}finally{cdp.off('HeapProfiler.addHeapSnapshotChunk',listener);closeSync(fd)}
    const b=readFileSync(path);report.snapshots.push({label,path,bytes:b.length,sha256:sha(b)});save()
    console.log('RETAINER_SNAPSHOT',label,b.length)
  }
  await visit(13,'warmup');await visit(12,'warmup')
  await collect('idle-before')
  for(let i=0;i<12;i++)await collect('idle-control-'+i)
  await snapshot('before')
  await collect('after-before-snapshot')
  await cdp.send('HeapProfiler.startSampling',{samplingInterval:8192})
  for(let i=0;i<2;i++){await visit(13,'repeat-'+i);await visit(12,'repeat-'+i)}
  const sampling=await cdp.send('HeapProfiler.stopSampling')
  const samplingPath=root+name+'-sampling.json'
  writeFileSync(samplingPath,JSON.stringify(sampling,null,2),{flag:'wx'})
  report.sampling={path:samplingPath,sha256:sha(readFileSync(samplingPath)),bytes:readFileSync(samplingPath).length}
  await page.waitForTimeout(10000)
  await collect('final-idle');await snapshot('after');await collect('after-final-snapshot')
  report.restoration=await page.evaluate(()=>window.__memorySoak.restore())
  assert.deepEqual(report.restoration,{contexts:1,restored:true})
  for(const key of ['errors','warnings','assetFailures'])assert.deepEqual(report[key],[],key)
  for(const [p,h] of Object.entries(report.sourceHashes))assert.equal(sha(readFileSync(p)),h,p)
  report.outcome='completed'
}catch(error){report.failure=error.stack||error.message;console.error(error);process.exitCode=1}
finally{report.finishedAt=new Date().toISOString();save();await cdp?.detach();await browser?.close();if(server)await new Promise(resolve=>server.httpServer.close(resolve))}

