import {readFileSync,writeFileSync} from 'node:fs'
import {createHash} from 'node:crypto'
import assert from 'node:assert/strict'
const root='benchmark-results/heavy-scenes/',name='production-memory-retainers-2026-10-28'
const sha=b=>createHash('sha256').update(b).digest('hex'),json=p=>JSON.parse(readFileSync(p,'utf8'))
const report=json(root+name+'.json')
assert.equal(report.outcome,'completed')
for(const s of report.snapshots){const b=readFileSync(s.path);assert.equal(b.length,s.bytes);assert.equal(sha(b),s.sha256)}
const before=json(report.snapshots[0].path),after=json(report.snapshots[1].path)
function grouped(heap){
  const fields=heap.snapshot.meta.node_fields,width=fields.length,types=heap.snapshot.meta.node_types[fields.indexOf('type')]
  const out=new Map(),ids=new Set()
  for(let i=0;i<heap.nodes.length;i+=width){
    const type=types[heap.nodes[i+fields.indexOf('type')]],name=heap.strings[heap.nodes[i+fields.indexOf('name')]],id=heap.nodes[i+fields.indexOf('id')]
    const bytes=heap.nodes[i+fields.indexOf('self_size')],key=type+':'+name
    const group=out.get(key)||{type,name,count:0,bytes:0,ids:[]}
    group.count++;group.bytes+=bytes;group.ids.push(id);out.set(key,group);ids.add(id)
  }
  return {groups:out,ids}
}
const a=grouped(before),b=grouped(after)
const deltas=[...new Set([...a.groups.keys(),...b.groups.keys()])].map(key=>{
  const x=a.groups.get(key),y=b.groups.get(key),value=y||x
  return {type:value.type,name:value.name,countBefore:x?.count||0,countAfter:y?.count||0,countDelta:(y?.count||0)-(x?.count||0),
    bytesBefore:x?.bytes||0,bytesAfter:y?.bytes||0,bytesDelta:(y?.bytes||0)-(x?.bytes||0),newIds:(y?.ids||[]).filter(id=>!a.ids.has(id)).slice(0,5)}
})
const byType={}
for(const d of deltas){const row=byType[d.type]??={countDelta:0,bytesDelta:0};row.countDelta+=d.countDelta;row.bytesDelta+=d.bytesDelta}
const sampling=json(report.sampling.path)
assert.equal(sha(readFileSync(report.sampling.path)),report.sampling.sha256)
const allocations=[]
function walk(node,parents=[]){
  if(node.selfSize>0)allocations.push({id:node.id,selfSize:node.selfSize,callFrame:node.callFrame,parents})
  for(const child of node.children)walk(child,[...parents,node.callFrame])
}
walk(sampling.profile.head)
allocations.sort((a,b)=>b.selfSize-a.selfSize)
// Inspect concrete retaining paths. Weak edges are excluded; this is not a
// dominator calculation and does not resolve ephemeron reachability conditions.
function retainingPaths(heap,ids){
  const nf=heap.snapshot.meta.node_fields,ef=heap.snapshot.meta.edge_fields,nw=nf.length,ew=ef.length,n=heap.nodes.length/nw
  const nt=heap.snapshot.meta.node_types[nf.indexOf('type')],et=heap.snapshot.meta.edge_types[ef.indexOf('type')]
  const nodeField=(i,k)=>heap.nodes[i*nw+nf.indexOf(k)],edgeField=(i,k)=>heap.edges[i+ef.indexOf(k)]
  const describe=i=>({id:nodeField(i,'id'),type:nt[nodeField(i,'type')],name:heap.strings[nodeField(i,'name')]})
  const counts=new Uint32Array(n),offsets=new Uint32Array(n+1),indices=new Map()
  let e=0
  for(let i=0;i<n;i++){
    if(ids.includes(nodeField(i,'id')))indices.set(nodeField(i,'id'),i)
    for(let j=0;j<nodeField(i,'edge_count');j++,e+=ew)if(et[edgeField(e,'type')]!=='weak')counts[edgeField(e,'to_node')/nw]++
  }
  for(let i=0;i<n;i++)offsets[i+1]=offsets[i]+counts[i]
  const cursor=offsets.slice(),sources=new Uint32Array(offsets[n]),edgeOffsets=new Uint32Array(offsets[n]);e=0
  for(let i=0;i<n;i++)for(let j=0;j<nodeField(i,'edge_count');j++,e+=ew){
    if(et[edgeField(e,'type')]==='weak')continue
    const to=edgeField(e,'to_node')/nw,at=cursor[to]++;sources[at]=i;edgeOffsets[at]=e
  }
  return ids.map(id=>{
    const target=indices.get(id);assert.notEqual(target,undefined)
    const next=new Int32Array(n).fill(-1),via=new Uint32Array(n),seen=new Uint8Array(n),queue=new Uint32Array(n)
    let head=0,tail=1;queue[0]=target;seen[target]=1
    while(head<tail&&!seen[0]){
      const current=queue[head++]
      for(let k=offsets[current];k<offsets[current+1];k++){
        const parent=sources[k];if(seen[parent])continue
        seen[parent]=1;next[parent]=current;via[parent]=edgeOffsets[k];queue[tail++]=parent
      }
    }
    const path=[]
    if(seen[0])for(let i=0;i!==target;i=next[i]){
      const edge=via[i],type=et[edgeField(edge,'type')],nameIndex=edgeField(edge,'name_or_index')
      path.push({from:describe(i),edgeType:type,edgeName:type==='element'||type==='hidden'?nameIndex:heap.strings[nameIndex],to:describe(next[i])})
    }
    return {target:describe(target),found:!!seen[0],path}
  })
}
const pathIds=['code:system / InstructionStream','native:blink::NetworkResourcesData::ResourceData','object:Object','object:Array']
  .flatMap(key=>deltas.find(d=>d.type+':'+d.name===key)?.newIds.slice(0,2)||[])
const paths=retainingPaths(after,pathIds)
const result={snapshotInputs:report.snapshots,samplingInput:report.sampling,
  before:{nodes:before.snapshot.node_count,edges:before.snapshot.edge_count},after:{nodes:after.snapshot.node_count,edges:after.snapshot.edge_count},
  byType,topGrowth:[...deltas].sort((a,b)=>b.bytesDelta-a.bytesDelta).slice(0,35),
  objectGrowth:deltas.filter(d=>d.type==='object').sort((a,b)=>b.bytesDelta-a.bytesDelta).slice(0,30),
  topRetainedAllocations:allocations.slice(0,30),sampledRetainedBytes:allocations.reduce((sum,x)=>sum+x.selfSize,0),
