import {readFileSync,writeFileSync,readdirSync,cpSync,existsSync} from 'node:fs'
import {execFileSync} from 'node:child_process'
import {createHash} from 'node:crypto'
import assert from 'node:assert/strict'
const root='benchmark-results/heavy-scenes/',frozenBundle=root+'render-list-fixed-dist-2026-10-28'
const sha=b=>createHash('sha256').update(b).digest('hex')
assert.equal(existsSync(frozenBundle),false,'Never overwrite an archived build')
const files=execFileSync('git',['ls-files','--','src','tests','package.json','package-lock.json','vite.config.ts','tsconfig.json','tsconfig.app.json'],{encoding:'utf8'}).trim().split(/\r?\n/)
const buildInputHashes=Object.fromEntries(files.map(p=>[p,sha(readFileSync(p))]))
cpSync('dist',frozenBundle,{recursive:true,errorOnExist:true,force:false})
function walk(path=''){
  return readdirSync(frozenBundle+'/'+path,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path+e.name+'/'):[path+e.name])
}
const buildFiles=walk().sort().map(path=>{const b=readFileSync(frozenBundle+'/'+path);return {path,bytes:b.length,sha256:sha(b)}})
const html=readFileSync(frozenBundle+'/index.html','utf8'),entryUrl=html.match(/<script[^>]+src="([^"]+)"/)[1]
const runtimes=buildFiles.filter(x=>/^assets\/simulationRuntime-[^/]+\.js$/.test(x.path));assert.equal(runtimes.length,1)
const connection={entryUrl,runtimeUrl:'/titan-engine-dev/'+runtimes[0].path}
const report={outcome:'built',base:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),frozenBundle,buildFiles,buildInputHashes,connection}
writeFileSync(root+'render-list-fixed-build-2026-10-28.json',JSON.stringify(report,null,2)+'\n',{flag:'wx'})
console.log(JSON.stringify({buildFiles:buildFiles.length,inputFiles:files.length,connection}))

